#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <openssl/evp.h>

static PyObject *encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    int has_aad;
    if (!PyArg_ParseTuple(args, "y*y*y*y*", &key, &nonce, &pt, &aad)) {
        /* try with None aad */
        PyErr_Clear();
        if (!PyArg_ParseTuple(args, "y*y*y*O", &key, &nonce, &pt, &self)) {
            return NULL;
        }
    }
    return NULL;
}

/* Simpler manual parsing */
static PyObject *aesgcm_encrypt(PyObject *self, PyObject *args) {
    PyObject *key_obj, *nonce_obj, *pt_obj, *aad_obj;
    if (!PyArg_ParseTuple(args, "OOOO", &key_obj, &nonce_obj, &pt_obj, &aad_obj))
        return NULL;

    Py_buffer key, nonce, pt, aad;
    memset(&aad, 0, sizeof(aad));
    if (PyObject_GetBuffer(key_obj, &key, PyBUF_SIMPLE) != 0) return NULL;
    if (PyObject_GetBuffer(nonce_obj, &nonce, PyBUF_SIMPLE) != 0) { PyBuffer_Release(&key); return NULL; }
    if (PyObject_GetBuffer(pt_obj, &pt, PyBUF_SIMPLE) != 0) { PyBuffer_Release(&nonce); PyBuffer_Release(&key); return NULL; }

    int have_aad = 0;
    if (aad_obj != Py_None) {
        if (PyObject_GetBuffer(aad_obj, &aad, PyBUF_SIMPLE) != 0) {
            PyBuffer_Release(&pt); PyBuffer_Release(&nonce); PyBuffer_Release(&key);
            return NULL;
        }
        have_aad = 1;
    }

    const EVP_CIPHER *cipher = NULL;
    if (key.len == 16) cipher = EVP_aes_128_gcm();
    else if (key.len == 24) cipher = EVP_aes_192_gcm();
    else if (key.len == 32) cipher = EVP_aes_256_gcm();
    else {
        PyErr_SetString(PyExc_ValueError, "bad key size");
        goto fail;
    }

    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, pt.len);
    if (!ct_obj) goto fail;
    PyObject *tag_obj = PyBytes_FromStringAndSize(NULL, 16);
    if (!tag_obj) { Py_DECREF(ct_obj); goto fail; }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) { Py_DECREF(ct_obj); Py_DECREF(tag_obj); goto fail; }

    int ok = 1;
    int outlen = 0;
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) ok = 0;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, (int)nonce.len, NULL) != 1) ok = 0;
    if (ok && EVP_EncryptInit_ex(ctx, NULL, NULL, key.buf, nonce.buf) != 1) ok = 0;
    if (ok && have_aad && aad.len > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outlen, aad.buf, (int)aad.len) != 1) ok = 0;
    }
    int total = 0;
    if (ok && pt.len > 0) {
        if (EVP_EncryptUpdate(ctx, (unsigned char *)PyBytes_AS_STRING(ct_obj), &outlen,
                              pt.buf, (int)pt.len) != 1) ok = 0;
        total = outlen;
    }
    if (ok && EVP_EncryptFinal_ex(ctx, (unsigned char *)PyBytes_AS_STRING(ct_obj) + total, &outlen) != 1) ok = 0;
    total += outlen;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, PyBytes_AS_STRING(tag_obj)) != 1) ok = 0;

    EVP_CIPHER_CTX_free(ctx);
    if (have_aad) PyBuffer_Release(&aad);
    PyBuffer_Release(&pt); PyBuffer_Release(&nonce); PyBuffer_Release(&key);

    if (!ok) {
        Py_DECREF(ct_obj); Py_DECREF(tag_obj);
        PyErr_SetString(PyExc_RuntimeError, "encrypt failed");
        return NULL;
    }
    if (total != pt.len) {
        if (_PyBytes_Resize(&ct_obj, total) != 0) { Py_DECREF(tag_obj); return NULL; }
    }
    return Py_BuildValue("NN", ct_obj, tag_obj);

fail:
    if (have_aad) PyBuffer_Release(&aad);
    PyBuffer_Release(&pt); PyBuffer_Release(&nonce); PyBuffer_Release(&key);
    return NULL;
}

static PyMethodDef methods[] = {
    {"encrypt", aesgcm_encrypt, METH_VARARGS, "AES-GCM encrypt"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "aesgcm", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_aesgcm(void) { return PyModule_Create(&moduledef); }
EOF
