{"command":"cd "$HOME/aesbuild" && cat > aesgcm2.c << 'EOF'
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <string.h>
#include <openssl/evp.h>

static EVP_CIPHER_CTX *g_ctx = NULL;

static PyObject *aesgcm_encrypt(PyObject *self, PyObject *args) {
    const unsigned char *key, *nonce, *pt, *aad;
    Py_ssize_t keylen, noncelen, ptlen, aadlen;
    PyObject *aad_obj;

    if (!PyArg_ParseTuple(args, "y#y#y#O", &key, &keylen, &nonce, &noncelen, &pt, &ptlen, &aad_obj))
        return NULL;

    if (aad_obj == Py_None) { aad = NULL; aadlen = 0; }
    else if (PyBytes_Check(aad_obj)) { aad = (const unsigned char *)PyBytes_AS_STRING(aad_obj); aadlen = PyBytes_GET_SIZE(aad_obj); }
    else {
        PyErr_SetString(PyExc_TypeError, "aad must be bytes or None");
        return NULL;
    }

    const EVP_CIPHER *cipher = NULL;
    if (keylen == 16) cipher = EVP_aes_128_gcm();
    else if (keylen == 24) cipher = EVP_aes_192_gcm();
    else if (keylen == 32) cipher = EVP_aes_256_gcm();
    else { PyErr_SetString(PyExc_ValueError, "bad key size"); return NULL; }

    if (!g_ctx) g_ctx = EVP_CIPHER_CTX_new();
    EVP_CIPHER_CTX *ctx = g_ctx;

    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, ptlen > 0 ? ptlen : 1);
    if (!ct_obj) return NULL;
    unsigned char tag[16];

    int ok = 1, outlen = 0, total = 0;
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) ok = 0;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, (int)noncelen, NULL) != 1) ok = 0;
    if (ok && EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce) != 1) ok = 0;
    if (ok && aad && aadlen > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outlen, aad, (int)aadlen) != 1) ok = 0;
    }
    unsigned char *out = (unsigned char *)PyBytes_AS_STRING(ct_obj);
    /* chunk */
    Py_ssize_t off = 0;
    const Py_ssize_t CHUNK = 1 << 20;
    while (ok && off < ptlen) {
        int n = (int)((ptlen - off) > CHUNK ? CHUNK : (ptlen - off));
        if (EVP_EncryptUpdate(ctx, out + off, &outlen, pt + off, n) != 1) { ok = 0; break; }
        off += outlen;
    }
    total = (int)off;
    if (ok && EVP_EncryptFinal_ex(ctx, out + total, &outlen) != 1) ok = 0;
    total += outlen;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag) != 1) ok = 0;

    if (!ok) { Py_DECREF(ct_obj); PyErr_SetString(PyExc_RuntimeError, "encrypt failed"); return NULL; }
    if (total != ptlen) { if (_PyBytes_Resize(&ct_obj, total) != 0) return NULL; }
    return Py_BuildValue("N y#", ct_obj, tag, (Py_ssize_t)16);
}

static PyMethodDef methods[] = {
    {"encrypt", aesgcm_encrypt, METH_VARARGS, ""},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = { PyModuleDef_HEAD_INIT, "aesgcm2", NULL, -1, methods };
PyMODINIT_FUNC PyInit_aesgcm2(void) { return PyModule_Create(&moduledef); }
EOF
