#include <emmintrin.h>
#include <smmintrin.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    size_t N = 60ull*1024*1024;
    uint8_t *src = aligned_alloc(64, N);
    uint8_t *dst = aligned_alloc(64, N);
    memset(src, 1, N);
    double t0 = now();
    for (int i = 0; i < 5; i++) memcpy(dst, src, N);
    double t1 = now();
    printf("memcpy %.4f s  %.0f MB/s\n", (t1-t0)/5, (N/1e6)/((t1-t0)/5));

    /* streaming load+store */
    t0 = now();
    for (int i = 0; i < 5; i++) {
        for (size_t j = 0; j < N; j += 64) {
