            _mm_storeu_si128(((__m128i*)dst)+j/16, a);
            _mm_storeu_si128(((__m128i*)dst)+j/16+1, b);
            _mm_storeu_si128(((__m128i*)dst)+j/16+2, c);
            _mm_storeu_si128(((__m128i*)dst)+j/16+3, d);
        }
