            x1 = _mm_aesenc_si128(x1, k);
            x2 = _mm_aesenc_si128(x2, k);
            x3 = _mm_aesenc_si128(x3, k);
            x4 = _mm_aesenc_si128(x4, k);
            x5 = _mm_aesenc_si128(x5, k);
            x6 = _mm_aesenc_si128(x6, k);
            x7 = _mm_aesenc_si128(x7, k);
        }
