    volatile int z = _mm_cvtsi128_si32(x0) ^ _mm_cvtsi128_si32(x7);
    printf("aesenc x8 %.4f s  %.0f MB/s (z=%d)\n", (t1-t0)/3, (N/1e6)/((t1-t0)/3), z);

    /* 10 rounds (AES-128) x8 independent, with load/store */
    t0 = now();
    for (int rep = 0; rep < 3; rep++) {
        for (size_t j = 0; j < N; j += 128) {
            __m128i a0 = _mm_loadu_si128((__m128i*)(src+j));
