#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <wmmintrin.h>
#include <openssl/evp.h>

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec + ts.tv_nsec*1e-9; }

static inline __m128i aes128_encrypt(__m128i b, const __m128i rk[11]) {
    b = _mm_xor_si128(b, rk[0]);
    b = _mm_aesenc_si128(b, rk[1]);
    b = _mm_aesenc_si128(b, rk[2]);
    b = _mm_aesenc_si128(b, rk[3]);
    b = _mm_aesenc_si128(b, rk[4]);
    b = _mm_aesenc_si128(b, rk[5]);
    b = _mm_aesenc_si128(b, rk[6]);
    b = _mm_aesenc_si128(b, rk[7]);
    b = _mm_aesenc_si128(b, rk[8]);
    b = _mm_aesenc_si128(b, rk[9]);
    b = _mm_aesenclast_si128(b, rk[10]);
    return b;
}

static void aes128_key_expand(const uint8_t key[16], __m128i rk[11]) {
    rk[0] = _mm_loadu_si128((const __m128i*)key);
    __m128i t = rk[0];
    #define EXPAND(i, rcon) do { \
        __m128i w = _mm_aeskeygenassist_si128(t, rcon); \
        w = _mm_shuffle_epi32(w, 0xff); \
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4)); \
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4)); \
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4)); \
        t = _mm_xor_si128(t, w); \
        rk[i] = t; \
    } while (0)
    EXPAND(1, 0x01); EXPAND(2, 0x02); EXPAND(3, 0x04); EXPAND(4, 0x08);
    EXPAND(5, 0x10); EXPAND(6, 0x20); EXPAND(7, 0x40); EXPAND(8, 0x80);
    EXPAND(9, 0x1b); EXPAND(10, 0x36);
}

/* reflect 128 bits */
static inline __m128i reflect(__m128i x) {
    /* byte swap then bit reverse each byte via shuffle? bit reverse is harder.
       Use a small lookup approach: for correctness test only, do scalar. */
    uint8_t b[16], o[16];
    _mm_storeu_si128((__m128i*)b, x);
    for (int i = 0; i < 16; i++) {
        uint8_t v = b[15 - i];
        uint8_t r = 0;
        for (int k = 0; k < 8; k++) r |= ((v >> k) & 1) << (7 - k);
        o[i] = r;
    }
    return _mm_loadu_si128((__m128i*)o);
}

static inline __m128i gmul(__m128i a, __m128i b) {
    /* carryless multiply of reflected operands, reduce mod x^128 + x^7 + x^2 + x + 1 (reflected: x^128 + x^127 + x^126 + x^121 + 1) */
    __m128i lo = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i hi = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i m1 = _mm_clmulepi64_si128(a, b, 0x01);
    __m128i m2 = _mm_clmulepi64_si128(a, b, 0x10);
    __m128i mid = _mm_xor_si128(m1, m2);
    lo = _mm_xor_si128(lo, _mm_slli_si128(mid, 8));
    hi = _mm_xor_si128(hi, _mm_srli_si128(mid, 8));
    /* reduction: reflected polynomial. Algorithm from Intel clmul gcm paper (reduction of the 256-bit product). */
    /* For reflected GHASH, reduction uses poly = 0xe1 << 120. */
    __m128i poly = _mm_set_epi64x(0xc200000000000000ULL, 0); /* 0xe1 reflected << 56? let's test empirically later */
    /* Use the two-phase reduction from Intel whitepaper for the *reflected* case:
       poly = 0x87 reflected into high = actually the constant is _mm_setr_epi32(0,0,0,0xc2000000) no.
       We'll implement reduction scalar for correctness first. */
    uint64_t L[2], H[2];
    _mm_storeu_si128((__m128i*)L, lo);
    _mm_storeu_si128((__m128i*)H, hi);
    /* 256-bit product in L[0], L[1], H[0], H[1] (little endian, L[0] is low 64).
       Reduce mod p(x) = x^128 + x^7 + x^2 + x + 1 in reflected representation,
       where reduction is: for bits above 127, XOR shifted by 128,127,126,121. */
    uint64_t z0 = L[0], z1 = L[1], z2 = H[0], z3 = H[1];
    /* reduction of z2,z3 into z0,z1. Reflected reduction (right shifts): */
    uint64_t t = z3;
    z1 ^= (t >> 63) ^ (t >> 62) ^ (t >> 57);
    z0 ^= (t << 1) ^ (t << 2) ^ (t << 7);
    t = z2;
    z1 ^= (t << 1) ^ (t << 2) ^ (t << 7);
    z0 ^= (t >> 63) ^ (t >> 62) ^ (t >> 57);
    uint64_t out[2] = {z0, z1};
    return _mm_loadu_si128((__m128i*)out);
}

static void ghash(const __m128i H, const uint8_t *data, size_t len, uint8_t out[16]) {
    __m128i y = _mm_setzero_si128();
    size_t n = len / 16;
    for (size_t i = 0; i < n; i++) {
        __m128i b = _mm_loadu_si128((const __m128i*)(data + 16*i));
        b = reflect(b);
        y = gmul(_mm_xor_si128(y, b), H);
    }
    if (len % 16) {
        uint8_t tmp[16] = {0};
        memcpy(tmp, data + 16*n, len % 16);
        __m128i b = reflect(_mm_loadu_si128((__m128i*)tmp));
        y = gmul(_mm_xor_si128(y, b), H);
    }
    _mm_storeu_si128((__m128i*)out, reflect(y));
}

static void gcm_encrypt_128(const uint8_t key[16], const uint8_t *nonce, int noncelen,
                            const uint8_t *pt, size_t ptlen,
                            const uint8_t *aad, size_t aadlen,
                            uint8_t *ct, uint8_t tag[16]) {
    __m128i rk[11];
    aes128_key_expand(key, rk);
    __m128i h = aes128_encrypt(_mm_setzero_si128(), rk);
    __m128i H = reflect(h);

    /* J0 */
    uint8_t j0[16];
    if (noncelen == 12) {
        memcpy(j0, nonce, 12);
        j0[12] = 0; j0[13] = 0; j0[14] = 0; j0[15] = 1;
    } else {
        /* GHASH of nonce padded */
        size_t padded = ((noncelen + 15) / 16) * 16 + 16;
        uint8_t *buf = calloc(1, padded);
        memcpy(buf, nonce, noncelen);
        uint64_t bits = (uint64_t)noncelen * 8;
        for (int i = 0; i < 8; i++) buf[padded - 1 - i] = (uint8_t)(bits >> (8*i));
        ghash(H, buf, padded, j0);
        free(buf);
    }
    __m128i J0 = _mm_loadu_si128((__m128i*)j0);
    __m128i ctr = J0;
    /* increment counter (big endian last 32 bits) */
    uint8_t cb[16];
    _mm_storeu_si128((__m128i*)cb, ctr);
    uint32_t c = ((uint32_t)cb[12] << 24) | ((uint32_t)cb[13] << 16) | ((uint32_t)cb[14] << 8) | cb[15];
    size_t blocks = (ptlen + 15) / 16;
    for (size_t i = 0; i < blocks; i++) {
        c += 1;
        cb[12] = c >> 24; cb[13] = c >> 16; cb[14] = c >> 8; cb[15] = c;
        __m128i ks = aes128_encrypt(_mm_loadu_si128((__m128i*)cb), rk);
        size_t off = i * 16;
        size_t n = ptlen - off; if (n > 16) n = 16;
        uint8_t block[16] = {0};
        memcpy(block, pt + off, n);
        __m128i p = _mm_loadu_si128((__m128i*)block);
        __m128i o = _mm_xor_si128(p, ks);
        uint8_t ob[16];
        _mm_storeu_si128((__m128i*)ob, o);
        memcpy(ct + off, ob, n);
    }
    /* GHASH over aad || ct || lengths */
    size_t aad_pad = (aadlen + 15) & ~15ull;
    size_t ct_pad = (ptlen + 15) & ~15ull;
    size_t total = aad_pad + ct_pad + 16;
    uint8_t *buf = calloc(1, total);
    if (aad && aadlen) memcpy(buf, aad, aadlen);
    memcpy(buf + aad_pad, ct, ptlen);
    uint64_t abits = (uint64_t)aadlen * 8, cbits = (uint64_t)ptlen * 8;
    uint8_t *lp = buf + aad_pad + ct_pad;
    for (int i = 0; i < 8; i++) lp[7 - i] = (uint8_t)(abits >> (8*i));
    for (int i = 0; i < 8; i++) lp[15 - i] = (uint8_t)(cbits >> (8*i));
    uint8_t s[16];
    ghash(H, buf, total, s);
    free(buf);
    __m128i ek0 = aes128_encrypt(J0, rk);
    __m128i tg = _mm_xor_si128(_mm_loadu_si128((__m128i*)s), ek0);
    _mm_storeu_si128((__m128i*)tag, tg);
}

int main() {
    uint8_t key[16], nonce[12], pt[1000], aad[32], ct[1000], tag[16];
    FILE *f = fopen("/dev/urandom","rb");
    fread(key,1,16,f); fread(nonce,1,12,f); fread(pt,1,1000,f); fread(aad,1,32,f); fclose(f);
    gcm_encrypt_128(key, nonce, 12, pt, 1000, aad, 32, ct, tag);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    int outlen = 0;
    EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
    uint8_t ct2[1000]; int total = 0;
    EVP_EncryptUpdate(ctx, ct2, &outlen, pt, 1000); total = outlen;
    EVP_EncryptFinal_ex(ctx, ct2 + total, &outlen); total += outlen;
    uint8_t tag2[16];
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag2);
    printf("ct match %d\n", memcmp(ct, ct2, 1000) == 0);
    printf("tag match %d\n", memcmp(tag, tag2, 16) == 0);
    if (memcmp(ct, ct2, 1000)) {
        for (int i = 0; i < 32; i++) printf("%02x/%02x ", ct[i], ct2[i]);
        printf("\n");
    }
    if (memcmp(tag, tag2, 16)) {
        for (int i = 0; i < 16; i++) printf("%02x/%02x ", tag[i], tag2[i]);
        printf("\n");
    }
    /* bench */
    size_t N = 60ull*1024*1024;
    uint8_t *big = malloc(N), *bigct = malloc(N);
    fread(big, 1, 4096, fopen("/dev/urandom","rb"));
    memset(big, 0x5a, N);
    uint8_t t[16];
    double t0 = now();
    gcm_encrypt_128(key, nonce, 12, big, N, aad, 32, bigct, t);
    double t1 = now();
    printf("my gcm %.4f s  %.0f MB/s\n", t1-t0, (N/1e6)/(t1-t0));
    return 0;
}
