    uint8_t href[16]; reflect_bytes(hb, href);
    uint8_t dref[32]; reflect_bytes(data, dref); reflect_bytes(data+16, dref+16);

    for (int refl_in = 0; refl_in < 2; refl_in++) {
      for (int refl_h = 0; refl_h < 2; refl_h++) {
        for (int mode = 0; mode < 4; mode++) {
          for (int refl_out = 0; refl_out < 2; refl_out++) {
