#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <wmmintrin.h>

static void reflect_bytes(const uint8_t in[16], uint8_t out[16]) {
    for (int i = 0; i < 16; i++) {
        uint8_t v = in[15 - i], r = 0;
        for (int k = 0; k < 8; k++) r |= ((v >> k) & 1) << (7 - k);
        out[i] = r;
    }
}
static void clmul256(const uint64_t a[2], const uint64_t b[2], uint64_t z[4]) {
    __m128i A = _mm_loadu_si128((const __m128i*)a);
    __m128i B = _mm_loadu_si128((const __m128i*)b);
    __m128i lo = _mm_clmulepi64_si128(A, B, 0x00);
    __m128i hi = _mm_clmulepi64_si128(A, B, 0x11);
    __m128i m1 = _mm_clmulepi64_si128(A, B, 0x01);
    __m128i m2 = _mm_clmulepi64_si128(A, B, 0x10);
    __m128i mid = _mm_xor_si128(m1, m2);
    uint64_t m[2]; _mm_storeu_si128((__m128i*)m, mid);
    _mm_storeu_si128((__m128i*)z, lo);
    _mm_storeu_si128((__m128i*)(z+2), hi);
    z[1] ^= m[0]; z[2] ^= m[1];
}
/* bit-level gmul in reflected representation to get ground truth, then compare to reduction variants */
static void gmul_bit(const uint8_t X[16], const uint8_t Y[16], uint8_t out[16]) {
    /* NIST bit ordering: bit 0 is MSB of byte 0. Multiplication in GF(2^128) with R = 11100001 || 0^120 */
    uint8_t Z[16] = {0};
    uint8_t V[16]; memcpy(V, Y, 16);
    for (int i = 0; i < 16; i++) {
        for (int j = 0; j < 8; j++) {
            if (X[i] & (0x80 >> j)) {
                for (int k = 0; k < 16; k++) Z[k] ^= V[k];
            }
            int lsb = V[15] & 1;
            for (int k = 15; k > 0; k--) V[k] = (V[k] >> 1) | (V[k-1] << 7);
            V[0] >>= 1;
            if (lsb) V[0] ^= 0xe1;
        }
    }
    memcpy(out, Z, 16);
}

int main() {
    uint8_t X[16] = {0x00,0x11,0x22,0x33,0x44,0x55,0x66,0x77,0x88,0x99,0xaa,0xbb,0xcc,0xdd,0xee,0xff};
    uint8_t Y[16] = {0x01,0x23,0x45,0x67,0x89,0xab,0xcd,0xef,0xfe,0xdc,0xba,0x98,0x76,0x54,0x32,0x10};
    uint8_t expect[16];
    gmul_bit(X, Y, expect);
    printf("expect: "); for (int i=0;i<16;i++) printf("%02x", expect[i]); printf("\n");

    uint8_t Xr[16], Yr[16]; reflect_bytes(X, Xr); reflect_bytes(Y, Yr);
    uint64_t xa[2], ya[2], xr[2], yr[2];
    memcpy(xa, X, 16); memcpy(ya, Y, 16); memcpy(xr, Xr, 16); memcpy(yr, Yr, 16);

    struct {const char *name; uint64_t *a; uint64_t *b;} inputs[] = {
        {"noref", xa, ya}, {"ref", xr, yr}
    };
    for (int ii = 0; ii < 2; ii++) {
        uint64_t z[4]; clmul256(inputs[ii].a, inputs[ii].b, z);
        printf("product %s: %016llx %016llx %016llx %016llx\n", inputs[ii].name, z[0], z[1], z[2], z[3]);
        /* try several reductions */
        for (int mode = 0; mode < 6; mode++) {
            uint64_t z0=z[0], z1=z[1], z2=z[2], z3=z[3];
            uint64_t o0, o1;
            if (mode==0) { /* reflected right shift, standard */
                uint64_t t=z3; z1^=(t>>63)^(t>>62)^(t>>57); z0^=(t<<1)^(t<<2)^(t<<7);
                t=z2; z1^=(t<<1)^(t<<2)^(t<<7); z0^=(t>>63)^(t>>62)^(t>>57);
                o0=z0; o1=z1;
            } else if (mode==1) { /* non-reflected left shift */
                uint64_t t=z0; z2^=(t<<63)^(t<<62)^(t<<57); z3^=(t>>1)^(t>>2)^(t>>7);
                t=z1; z2^=(t>>1)^(t>>2)^(t>>7); z3^=(t<<63)^(t<<62)^(t<<57);
                o0=z2; o1=z3;
            } else if (mode==2) { /* reflected, shifts 1,2,7 swapped direction sign */
                uint64_t t=z3; z1^=(t>>1)^(t>>2)^(t>>7); z0^=(t<<63)^(t<<62)^(t<<57);
                t=z2; z1^=(t<<63)^(t<<62)^(t<<57); z0^=(t>>1)^(t>>2)^(t>>7);
                o0=z0; o1=z1;
            } else if (mode==3) {
                uint64_t t=z3; z1^=(t<<63)^(t<<62)^(t<<57); z0^=(t>>1)^(t>>2)^(t>>7);
                t=z2; z1^=(t>>1)^(t>>2)^(t>>7); z0^=(t<<63)^(t<<62)^(t<<57);
                o0=z0; o1=z1;
            } else if (mode==4) { /* Gueron reduction reflected: shifts by 1,2,7 on the high half using the exact algorithm */
                /* From Gueron: v1 = z3, v0 = z2; then specific */
                uint64_t T = z2; uint64_t U = z3;
                z0 ^= (T << 1) ^ (T << 2) ^ (T << 7);
                z1 ^= (T >> 63) ^ (T >> 62) ^ (T >> 57);
                z1 ^= (U << 1) ^ (U << 2) ^ (U << 7);
                z0 ^= (U >> 63) ^ (U >> 62) ^ (U >> 57);
                o0 = z0; o1 = z1;
            } else { /* mode 5: reduction using the other convention of word order */
                uint64_t T = z3, U = z2;
                uint64_t r0 = z0 ^ (T<<1) ^ (T<<2) ^ (T<<7);
                uint64_t r1 = z1 ^ (T>>63) ^ (T>>62) ^ (T>>57) ^ (U<<1) ^ (U<<2) ^ (U<<7);
                r0 ^= (U>>63) ^ (U>>62) ^ (U>>57);
                o0 = r0; o1 = r1;
            }
            uint8_t out[16]; memcpy(out, &o0, 8); memcpy(out+8, &o1, 8);
            uint8_t outr[16]; reflect_bytes(out, outr);
            int m1 = memcmp(out, expect, 16)==0;
            int m2 = memcmp(outr, expect, 16)==0;
            if (m1 || m2) printf("MATCH input=%s mode=%d reflected_out=%d\n", inputs[ii].name, mode, m2 && !m1 ? 1 : 0);
        }
    }
    printf("done\n");
    return 0;
}
