    __m128i mid = _mm_xor_si128(_mm_clmulepi64_si128(A, B, 0x01), _mm_clmulepi64_si128(A, B, 0x10));
    uint8_t lob[16], hib[16], mb[16];
    _mm_storeu_si128((__m128i*)lob, lo);
    _mm_storeu_si128((__m128i*)hib, hi);
    _mm_storeu_si128((__m128i*)mb, mid);
    memcpy(z, lob, 16); memcpy(z+16, hib, 16);
    for (int i = 0; i < 16; i++) z[8+i] ^= mb[i];
}
static void gmul_bit(const uint8_t X[16], const uint8_t Y[16], uint8_t out[16]) {
    uint8_t Z[16] = {0}, V[16]; memcpy(V, Y, 16);
    for (int i = 0; i < 16; i++) for (int j = 0; j < 8; j++) {
        if (X[i] & (0x80 >> j)) for (int k = 0; k < 16; k++) Z[k] ^= V[k];
        int lsb = V[15] & 1;
        for (int k = 15; k > 0; k--) V[k] = (V[k] >> 1) | (V[k-1] << 7);
        V[0] >>= 1;
        if (lsb) V[0] ^= 0xe1;
    }
    memcpy(out, Z, 16);
}
/* shift a 256-bit little-endian array left by s bits (s < 64) */
static void shl(const uint8_t in[32], int s, uint8_t out[32]) {
    uint64_t w[4]; memcpy(w, in, 32);
    uint64_t o[4] = {0};
    for (int i = 0; i < 4; i++) {
        o[i] ^= w[i] << s;
        if (i+1 < 4) o[i+1] ^= w[i] >> (64 - s);
    }
    memcpy(out, o, 32);
}
static void shr(const uint8_t in[32], int s, uint8_t out[32]) {
    uint64_t w[4]; memcpy(w, in, 32);
    uint64_t o[4] = {0};
    for (int i = 0; i < 4; i++) {
        o[i] ^= w[i] >> s;
        if (i-1 >= 0) o[i-1] ^= w[i] << (64 - s);
    }
    memcpy(out, o, 32);
}
static void xor32(uint8_t a[32], const uint8_t b[32]) { for (int i=0;i<32;i++) a[i]^=b[i]; }

int main() {
    uint8_t X[16] = {0x00,0x11,0x22,0x33,0x44,0x55,0x66,0x77,0x88,0x99,0xaa,0xbb,0xcc,0xdd,0xee,0xff};
    uint8_t Y[16] = {0x01,0x23,0x45,0x67,0x89,0xab,0xcd,0xef,0xfe,0xdc,0xba,0x98,0x76,0x54,0x32,0x10};
    uint8_t expect[16]; gmul_bit(X, Y, expect);
    printf("expect: "); for (int i=0;i<16;i++) printf("%02x", expect[i]); printf("\n");

    uint8_t Xr[16], Yr[16]; reflect_bytes(X, Xr); reflect_bytes(Y, Yr);
    uint8_t prod_ref[32], prod_noref[32];
    clmul256(Xr, Yr, prod_ref);
    clmul256(X, Y, prod_noref);

    /* For reflected inputs, the product is in reflected bit order. Reduction mod reflected poly.
       Reflected poly p(x) = x^128 + x^127 + x^126 + x^121 + 1. Reducing the high 128 bits:
       x^128 = x^127 + x^126 + x^121 + 1, so XOR high part shifted right by 1,2,7 and by 128. */
    uint8_t hi[32] = {0}; memcpy(hi, prod_ref+16, 16);
    uint8_t acc[32]; memcpy(acc, prod_ref, 32);
    /* zero the high half and fold */
    memset(acc+16, 0, 16);
    uint8_t t[32];
    shr(hi, 1, t); xor32(acc, t);
    shr(hi, 2, t); xor32(acc, t);
    shr(hi, 7, t); xor32(acc, t);
    /* hi itself corresponds to shift by 128 already included? x^128 term: the low 128 of hi*x^128 contributes hi shifted 0 into low? 
       hi is bits 128..255. x^(128+k) = x^k * x^128 = x^k*(x^127+x^126+x^121+1) = x^(k+127)+...+x^k.
       So contribution to low 128 is hi shifted RIGHT by 1,2,7 (the x^k term from +1 gives bits k where k<128 i.e. the low 128 bits of hi, which is all of hi since hi<128 bits stored). 
       Wait hi holds exactly bits 128..255, so the +1 term contributes hi placed at bits 0..127. */
    xor32(acc, hi); /* but hi has zeros in low half; need to place high bits into low */
    /* redo properly */
    memset(acc, 0, 32);
    memcpy(acc, prod_ref, 16);          /* low 128 bits */
    uint8_t hi_low[32] = {0}; memcpy(hi_low, prod_ref+16, 16); /* place bits 128..255 at position 0 */
    xor32(acc, hi_low);                  /* +1 term */
    shr(hi_low, 1, t); xor32(acc, t);    /* x^127 term -> shift right 1 */
    shr(hi_low, 2, t); xor32(acc, t);
    shr(hi_low, 7, t); xor32(acc, t);
    uint8_t out[16]; memcpy(out, acc, 16);
    uint8_t outr[16]; reflect_bytes(out, outr);
    printf("reflected reduction direct: "); for (int i=0;i<16;i++) printf("%02x", out[i]); printf(" match_direct=%d\n", memcmp(out, expect,16)==0);
    printf("reflected then reflect back: "); for (int i=0;i<16;i++) printf("%02x", outr[i]); printf(" match=%d\n", memcmp(outr, expect,16)==0);

    /* Also try the Gueron/Kounavis fast reduction algorithm exactly as published, on reflected operands, compare */
    return 0;
}
