#include <stdio.h>
#include <string.h>
#include <stdint.h>

static int getbit_le(const uint8_t *a, int n, int i) { if (i<0||i>=n) return 0; return (a[i/8] >> (i%8)) & 1; }
static void setbit_le(uint8_t *a, int i) { a[i/8] |= 1 << (i%8); }
static int getbit_nist(const uint8_t *a, int i) { return (a[i/8] >> (7 - (i%8))) & 1; }

static void reflect128(const uint8_t in[16], uint8_t out[16]) {
    memset(out, 0, 16);
    for (int i = 0; i < 128; i++) if (getbit_nist(in, i)) setbit_le(out, i);
}

/* schoolbook multiply, LE bit order */
static void mul256(const uint8_t a[16], const uint8_t b[16], uint8_t out[32]) {
    memset(out, 0, 32);
    for (int i = 0; i < 128; i++) if (getbit_le(a,128,i))
        for (int j = 0; j < 128; j++) if (getbit_le(b,128,j))
            out[(i+j)/8] ^= 1 << ((i+j)%8);
}

int main() {
    uint8_t X[16] = {0x00,0x11,0x22,0x33,0x44,0x55,0x66,0x77,0x88,0x99,0xaa,0xbb,0xcc,0xdd,0xee,0xff};
    uint8_t Y[16] = {0x01,0x23,0x45,0x67,0x89,0xab,0xcd,0xef,0xfe,0xdc,0xba,0x98,0x76,0x54,0x32,0x10};
    /* expected from earlier bit implementation */
    uint8_t expect[16];
    /* recompute expected with NIST bit order directly */
    uint8_t Z[16]={0}, V[16]; memcpy(V, Y, 16);
    for (int i = 0; i < 128; i++) {
        if (getbit_nist(X, i)) for (int k=0;k<16;k++) Z[k]^=V[k];
        int lsb = V[15] & 1;
        for (int k=15;k>0;k--) V[k] = (V[k]>>1) | (V[k-1]<<7);
        V[0] >>= 1;
        if (lsb) V[0] ^= 0xe1;
    }
    memcpy(expect, Z, 16);
    printf("expect: "); for (int i=0;i<16;i++) printf("%02x", expect[i]); printf("\n");

    uint8_t Xr[16], Yr[16]; reflect128(X, Xr); reflect128(Y, Yr);
    printf("Xr: "); for (int i=0;i<16;i++) printf("%02x", Xr[i]); printf("\n");
    uint8_t prod[32]; mul256(Xr, Yr, prod);
    printf("prod low: "); for (int i=0;i<16;i++) printf("%02x", prod[i]); printf("\n");
    printf("prod hi : "); for (int i=16;i<32;i++) printf("%02x", prod[i]); printf("\n");

    /* fold high 128 bits: x^(128+k) = x^k + x^(k+121) + x^(k+126) + x^(k+127) */
    uint8_t acc[32]; memset(acc, 0, 32); memcpy(acc, prod, 16);
    for (int k = 0; k < 128; k++) if (getbit_le(prod+16, 128, k)) {
        int shifts[4] = {k, k+121, k+126, k+127};
        for (int s = 0; s < 4; s++) {
            int bit = shifts[s];
            if (bit < 128) acc[bit/8] ^= 1 << (bit%8);
            else if (bit < 256) { /* second fold: bit-128 in high again */
                int k2 = bit - 128;
                int sh2[4] = {k2, k2+121, k2+126, k2+127};
                for (int t2 = 0; t2 < 4; t2++) {
                    int b2 = sh2[t2];
                    if (b2 < 128) acc[b2/8] ^= 1 << (b2%8);
                    else { int k3 = b2-128; int sh3[4]={k3,k3+121,k3+126,k3+127};
                        for (int t3=0;t3<4;t3++) if (sh3[t3] < 128) acc[sh3[t3]/8] ^= 1<<(sh3[t3]%8); }
                }
            }
