    printf("hi "); for (int i=0;i<16;i++) printf("%02x", hib[i]); printf("\n");

    /* Published algorithm (Gueron, "Fast GHASH", Figure 5), reflected domain:
       POLY = 0x...c200000000000000 (the high 64 bits) */
    const __m128i POLY = _mm_set_epi64x(0xc200000000000000ULL, 0);
    __m128i t1 = _mm_clmulepi64_si128(lo, POLY, 0x00); /* lo.low64 * poly.low64 = 0 */
    __m128i t2 = _mm_clmulepi64_si128(lo, POLY, 0x01); /* lo.low64 * poly.high64 */
    __m128i t3 = _mm_clmulepi64_si128(lo, POLY, 0x10); /* lo.high64 * poly.low64 = 0 */
    __m128i t4 = _mm_clmulepi64_si128(lo, POLY, 0x11); /* lo.high64 * poly.high64 */
    (void)t1; (void)t3;
    /* two-phase reduction as in the paper:
       D = X0
       T = D.low * poly.high   (t2)
