        for (int k = 0; k < 8; k++) r |= ((v >> k) & 1) << (7-k);
        out[i] = r;
    }
}
static int gbit(const uint8_t *a, int i) { return (a[i>>3] >> (i & 7)) & 1; }
static void sbit(uint8_t *a, int i) { a[i>>3] |= 1 << (i & 7); }

static void mulreflected(const uint8_t X[16], const uint8_t Y[16], uint8_t out[16]) {
    uint8_t Xr[16], Yr[16];
    reflect128(X, Xr); reflect128(Y, Yr);
    __m128i A = _mm_loadu_si128((__m128i*)Xr);
    __m128i B = _mm_loadu_si128((__m128i*)Yr);
    __m128i lo = _mm_clmulepi64_si128(A, B, 0x00);
    __m128i hi = _mm_clmulepi64_si128(A, B, 0x11);
    __m128i mid = _mm_xor_si128(_mm_clmulepi64_si128(A, B, 0x10), _mm_clmulepi64_si128(A, B, 0x01));
    uint8_t prod[32] = {0};
    uint8_t lob[16], hib[16], mb[16];
    _mm_storeu_si128((__m128i*)lob, lo);
    _mm_storeu_si128((__m128i*)hib, hi);
    _mm_storeu_si128((__m128i*)mb, mid);
    memcpy(prod, lob, 16); memcpy(prod+16, hib, 16);
    for (int i = 0; i < 16; i++) prod[8+i] ^= mb[i];

    /* fold bits 128..255: x^(128+k) = x^k + x^(k+121) + x^(k+126) + x^(k+127) */
    uint8_t acc[48]; memset(acc, 0, 48); memcpy(acc, prod, 16);
    for (int k = 0; k < 128; k++) if (gbit(prod+16, k)) {
        int pos[4] = {k, k+121, k+126, k+127};
        for (int t = 0; t < 4; t++) sbit(acc, pos[t]);
    }
    /* fold bits 128..255 again (and beyond) until clear */
    for (int pass = 0; pass < 4; pass++) {
        for (int k = 0; k < 128; k++) if (gbit(acc+16, k)) {
            acc[16 + (k>>3)] ^= 1 << (k & 7); /* clear */
            int pos[4] = {k, k+121, k+126, k+127};
            for (int t = 0; t < 4; t++) sbit(acc, pos[t]);
        }
    }
    /* reflect back */
    reflect128(acc, out);
}

int main() {
    uint8_t X[16] = {0x00,0x11,0x22,0x33,0x44,0x55,0x66,0x77,0x88,0x99,0xaa,0xbb,0xcc,0xdd,0xee,0xff};
