    uint8_t A3[16]={0}, B3[16]={0x80}; A3[15]=0x01; /* bit127 * bit0 = bit127 -> needs reduction: x^127 = ? no, bit127 is x^127, within range, result byte15 = 0x01 */
    mulreflected(A3, B3, out);
    printf("bit127*bit0 = "); for (int i=0;i<16;i++) printf("%02x", out[i]); printf("\n");
    uint8_t A4[16]={0}, B4[16]={0x40}; A4[15]=0x01; /* bit127 * bit1 = bit128 -> reduction: x^128 = x^7+x^2+x+1 -> 0xe1 in byte0? R = 11100001 = 0xe1 at top. x^128 reduces to x^7+x^2+x+1 which is bits 120..127? Let me just print */
