#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <wmmintrin.h>

static void reflect_byte_array(const uint8_t *in, uint8_t *out, int n) {
    for (int i = 0; i < n; i++) {
        uint8_t v = in[n-1-i], r = 0;
        for (int k = 0; k < 8; k++) r |= ((v >> k) & 1) << (7-k);
        out[i] = r;
    }
}
/* multiply two 16-byte NIST-order values using clmul on their bit-reflections stored
   little-endian (byte 0 = bits 0..7), reduce, reflect back. */
static void gmul(const uint8_t X[16], const uint8_t Y[16], uint8_t out[16]) {
    uint8_t Xr[16], Yr[16];
    reflect_byte_array(X, Xr, 16);
    reflect_byte_array(Y, Yr, 16);
    /* Now Xr[0] holds bits 0..7 (NIST bit 120..127 reversed?). Let's not assume; instead verify with test.
       Build 128-bit LE value where bit i (NIST index) is at position i. reflect_byte_array maps
       NIST bit i to LE bit i. Good: out[j] bit k = in[15-j] bit (7-k) = NIST bit ((15-j)*8 + (7-k)).
       We want NIST bit i -> LE bit i. NIST bit i lives at byte i/8, bit 7-(i%8). 
       reflect puts in[15-j] bit (7-k) into out[j] bit k. Set equal to NIST bit i = (15-j)*8 + (7-k).
       i = 120 - 8j + 7 - k = 127 - (8j + k). So out[j] bit k = NIST bit (127 - (8j+k)), i.e. the whole
       128-bit string is reversed, not identity. So reflect_byte_array gives bit-reversal, which is what we want
       for the reflected representation: LE bit i = NIST bit (127-i). That's the standard reflection. */
    __m128i A = _mm_loadu_si128((__m128i*)Xr);
    __m128i B = _mm_loadu_si128((__m128i*)Yr);
    __m128i lo = _mm_clmulepi64_si128(A, B, 0x00);
    __m128i hi = _mm_clmulepi64_si128(A, B, 0x11);
    __m128i mid = _mm_xor_si128(_mm_clmulepi64_si128(A, B, 0x10), _mm_clmulepi64_si128(A, B, 0x01));
    uint8_t prod[32] = {0}, lob[16], hib[16], mb[16];
    _mm_storeu_si128((__m128i*)lob, lo);
    _mm_storeu_si128((__m128i*)hib, hi);
    _mm_storeu_si128((__m128i*)mb, mid);
