#include <wmmintrin.h>

/* Map NIST bit i (MSB-first) to LE bit i (byte i/8, bit i%8). */
static void nist_to_le(const uint8_t in[16], uint8_t out[16]) {
    memset(out, 0, 16);
    for (int i = 0; i < 128; i++) {
        int nist = (in[i>>3] >> (7-(i&7))) & 1;
        if (nist) out[i>>3] |= 1 << (i&7);
    }
}
static void le_to_nist(const uint8_t in[16], uint8_t out[16]) {
    memset(out, 0, 16);
    for (int i = 0; i < 128; i++) if ((in[i>>3] >> (i&7)) & 1) out[i>>3] |= 0x80 >> (i&7);
}
static void gmul(const uint8_t X[16], const uint8_t Y[16], uint8_t out[16]) {
    uint8_t Xl[16], Yl[16];
    nist_to_le(X, Xl); nist_to_le(Y, Yl);
    __m128i A = _mm_loadu_si128((__m128i*)Xl);
    __m128i B = _mm_loadu_si128((__m128i*)Yl);
    __m128i lo = _mm_clmulepi64_si128(A, B, 0x00);
    __m128i hi = _mm_clmulepi64_si128(A, B, 0x11);
    __m128i mid = _mm_xor_si128(_mm_clmulepi64_si128(A, B, 0x10), _mm_clmulepi64_si128(A, B, 0x01));
    uint8_t prod[40]; memset(prod, 0, 40);
    uint8_t lob[16], hib[16], mb[16];
    _mm_storeu_si128((__m128i*)lob, lo); _mm_storeu_si128((__m128i*)hib, hi); _mm_storeu_si128((__m128i*)mb, mid);
    memcpy(prod, lob, 16); memcpy(prod+16, hib, 16);
    for (int i = 0; i < 16; i++) prod[8+i] ^= mb[i];
    /* x^(128+k) = x^(k+7) + x^(k+2) + x^(k+1) + x^k   (since x^128 = x^7+x^2+x+1) */
    for (int bit = 255; bit >= 128; bit--) {
        if ((prod[bit>>3] >> (bit & 7)) & 1) {
            prod[bit>>3] ^= 1 << (bit & 7);
            int base = bit - 128;
            int pos[4] = {base+7, base+2, base+1, base};
            for (int t = 0; t < 4; t++) prod[pos[t]>>3] ^= 1 << (pos[t] & 7);
        }
    }
    le_to_nist(prod, out);
