int main() {
    uint8_t X[16], Y[16], Z[16], out[16];
    int pairs[][2] = {{0,0},{1,0},{7,0},{127,1},{64,64},{5,123},{100,50},{127,127},{3,9},{20,40}};
    int ok = 1;
    for (int ti = 0; ti < 10; ti++) {
