int main() {
    /* We want output byte position where LE bit (8*j + k) comes from NIST bit (8*j + k).
       NIST bit i is at byte i/8, bit 7-(i%8). After a pshufb byte permutation, byte j of output = byte src[j] of input.
       We also need bit reversal within bytes. Do bit reversal first (within byte), then figure byte perm.
       Within a byte, NIST bits of byte b are NIST bits 8b..8b+7 at bit positions 7..0.
       LE wants bit (8b+t) at byte (8b+t)/8 = b, bit (8b+t)%8 = t. So within byte b, LE bit t should equal NIST bit (8b+t) = byte b bit (7-t).
       So bit reversal within each byte, NO byte permutation, gives exactly LE bit i = NIST bit i. */
    uint8_t in[16];
    for (int i = 0; i < 16; i++) in[i] = 0x80; /* NIST bit 0 of each byte set */
    /* apply bit reversal per byte */
    for (int i = 0; i < 16; i++) {
        uint8_t v = in[i], r = 0;
        for (int k = 0; k < 8; k++) r |= ((v >> k) & 1) << (7-k);
        in[i] = r;
    }
    printf("after bitreverse of 0x80 bytes: "); for (int i=0;i<16;i++) printf("%02x", in[i]); printf("\n");
    printf("So mask is identity byte perm + bit reversal. The SIMD version must be wrong in bit reversal.\n");
    return 0;
}
