    a = _mm_and_si128(_mm_srli_epi16(x, 4), _mm_set1_epi8(0x0f));
    b = _mm_and_si128(_mm_slli_epi16(x, 4), _mm_set1_epi8(0xf0));
    x = _mm_or_si128(a, b);
    return x;
}

