{"command":"cd "$HOME/aesbuild" && cat > gcmbench.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <wmmintrin.h>
#include <tmmintrin.h>
#include <openssl/evp.h>

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec + ts.tv_nsec*1e-9; }

static inline __m128i bswap_bits(__m128i x) {
    __m128i a = _mm_and_si128(_mm_srli_epi16(x, 1), _mm_set1_epi8(0x55));
    __m128i b = _mm_and_si128(_mm_slli_epi16(x, 1), _mm_set1_epi8(0xaa));
    x = _mm_or_si128(a, b);
    a = _mm_and_si128(_mm_srli_epi16(x, 2), _mm_set1_epi8(0x33));
    b = _mm_and_si128(_mm_slli_epi16(x, 2), _mm_set1_epi8(0xcc));
    x = _mm_or_si128(a, b);
    a = _mm_and_si128(_mm_srli_epi16(x, 4), _mm_set1_epi8(0x0f));
    b = _mm_and_si128(_mm_slli_epi16(x, 4), _mm_set1_epi8(0xf0));
    return _mm_or_si128(a, b);
}

static inline void fold(uint64_t *lo0, uint64_t *lo1, uint64_t hi0, uint64_t hi1) {
    uint64_t r0 = hi0 ^ (hi0 << 1) ^ (hi0 << 2) ^ (hi0 << 7);
    uint64_t c0 = (hi0 >> 63) ^ (hi0 >> 62) ^ (hi0 >> 57);
    uint64_t r1 = hi1 ^ (hi1 << 1) ^ (hi1 << 2) ^ (hi1 << 7);
    uint64_t c1 = (hi1 >> 63) ^ (hi1 >> 62) ^ (hi1 >> 57);
    *lo0 ^= r0; *lo1 ^= c0 ^ r1;
    *lo0 ^= c1 ^ (c1 << 1) ^ (c1 << 2) ^ (c1 << 7);
    uint64_t ec = (c1 >> 63) ^ (c1 >> 62) ^ (c1 >> 57);
    *lo1 ^= ec;
    if (ec) { *lo0 ^= ec ^ (ec << 1) ^ (ec << 2) ^ (ec << 7); *lo1 ^= (ec >> 63) ^ (ec >> 62) ^ (ec >> 57); }
}

static inline __m128i gmul(__m128i X, __m128i Y) {
    __m128i Xl = bswap_bits(X), Yl = bswap_bits(Y);
    __m128i lo = _mm_clmulepi64_si128(Xl, Yl, 0x00);
    __m128i hi = _mm_clmulepi64_si128(Xl, Yl, 0x11);
    __m128i mid = _mm_xor_si128(_mm_clmulepi64_si128(Xl, Yl, 0x10), _mm_clmulepi64_si128(Xl, Yl, 0x01));
    uint64_t L[2], H[2], M[2];
    _mm_storeu_si128((__m128i*)L, lo);
    _mm_storeu_si128((__m128i*)H, hi);
    _mm_storeu_si128((__m128i*)M, mid);
    L[1] ^= M[0]; H[0] ^= M[1];
    fold(&L[0], &L[1], H[0], H[1]);
    return bswap_bits(_mm_loadu_si128((__m128i*)L));
}

static void aes128_key_expand(const uint8_t key[16], __m128i rk[11]) {
    rk[0] = _mm_loadu_si128((const __m128i*)key);
    __m128i t = rk[0];
    #define EXPAND(i, rcon) do { __m128i w = _mm_aeskeygenassist_si128(t, rcon); w = _mm_shuffle_epi32(w, 0xff); \
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4)); t = _mm_xor_si128(t, _mm_slli_si128(t, 4)); \
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4)); t = _mm_xor_si128(t, w); rk[i] = t; } while (0)
    EXPAND(1,0x01);EXPAND(2,0x02);EXPAND(3,0x04);EXPAND(4,0x08);EXPAND(5,0x10);
    EXPAND(6,0x20);EXPAND(7,0x40);EXPAND(8,0x80);EXPAND(9,0x1b);EXPAND(10,0x36);
}
static inline __m128i aes128_encrypt(__m128i b, const __m128i rk[11]) {
    b = _mm_xor_si128(b, rk[0]);
    b = _mm_aesenc_si128(b, rk[1]); b = _mm_aesenc_si128(b, rk[2]); b = _mm_aesenc_si128(b, rk[3]);
    b = _mm_aesenc_si128(b, rk[4]); b = _mm_aesenc_si128(b, rk[5]); b = _mm_aesenc_si128(b, rk[6]);
    b = _mm_aesenc_si128(b, rk[7]); b = _mm_aesenc_si128(b, rk[8]); b = _mm_aesenc_si128(b, rk[9]);
    return _mm_aesenclast_si128(b, rk[10]);
}
static inline __m128i incr(__m128i c) {
    uint8_t b[16]; _mm_storeu_si128((__m128i*)b, c);
    uint32_t n = ((uint32_t)b[12] << 24) | ((uint32_t)b[13] << 16) | ((uint32_t)b[14] << 8) | b[15];
    n += 1;
    b[12] = n >> 24; b[13] = n >> 16; b[14] = n >> 8; b[15] = n;
    return _mm_loadu_si128((__m128i*)b);
}

static void ghash_blocks(__m128i H, const uint8_t *data, size_t len, __m128i *y) {
    size_t n = len / 16;
    for (size_t i = 0; i < n; i++) {
        __m128i b = _mm_loadu_si128((const __m128i*)(data + 16*i));
        *y = gmul(_mm_xor_si128(*y, b), H);
    }
    if (len % 16) {
        uint8_t tmp[16] = {0};
        memcpy(tmp, data + 16*n, len % 16);
        *y = gmul(_mm_xor_si128(*y, _mm_loadu_si128((__m128i*)tmp)), H);
    }
}

static void gcm_encrypt(const uint8_t key[16], const uint8_t *nonce, int noncelen,
                        const uint8_t *pt, size_t ptlen, const uint8_t *aad, size_t aadlen,
                        uint8_t *ct, uint8_t tag[16]) {
    __m128i rk[11]; aes128_key_expand(key, rk);
    __m128i H = aes128_encrypt(_mm_setzero_si128(), rk);
    __m128i J0;
    if (noncelen == 12) {
        uint8_t j0[16]; memcpy(j0, nonce, 12); j0[12]=0; j0[13]=0; j0[14]=0; j0[15]=1;
        J0 = _mm_loadu_si128((__m128i*)j0);
    } else {
        size_t padded = ((noncelen + 15) / 16) * 16;
        uint8_t *buf = calloc(1, padded + 16);
        memcpy(buf, nonce, noncelen);
        uint64_t bits = (uint64_t)noncelen * 8;
        for (int i = 0; i < 8; i++) buf[padded + 15 - i] = (uint8_t)(bits >> (8*i));
        __m128i y = _mm_setzero_si128();
        ghash_blocks(H, buf, padded + 16, &y);
        J0 = y; free(buf);
    }
    __m128i ctr = J0;
    size_t blocks = ptlen / 16;
    for (size_t i = 0; i < blocks; i++) {
        ctr = incr(ctr);
        __m128i ks = aes128_encrypt(ctr, rk);
        __m128i p = _mm_loadu_si128((const __m128i*)(pt + 16*i));
        _mm_storeu_si128((__m128i*)(ct + 16*i), _mm_xor_si128(p, ks));
    }
    if (ptlen % 16) {
        ctr = incr(ctr);
        __m128i ks = aes128_encrypt(ctr, rk);
        uint8_t block[16] = {0}, ob[16];
        memcpy(block, pt + 16*blocks, ptlen % 16);
        _mm_storeu_si128((__m128i*)ob, _mm_xor_si128(_mm_loadu_si128((__m128i*)block), ks));
        memcpy(ct + 16*blocks, ob, ptlen % 16);
    }
    __m128i y = _mm_setzero_si128();
    if (aad && aadlen) ghash_blocks(H, aad, aadlen, &y);
    ghash_blocks(H, ct, ptlen, &y);
    uint8_t lenblock[16] = {0};
    uint64_t abits = (uint64_t)aadlen * 8, cbits = (uint64_t)ptlen * 8;
    for (int i = 0; i < 8; i++) lenblock[7 - i] = (uint8_t)(abits >> (8*i));
    for (int i = 0; i < 8; i++) lenblock[15 - i] = (uint8_t)(cbits >> (8*i));
    y = gmul(_mm_xor_si128(y, _mm_loadu_si128((__m128i*)lenblock)), H);
    __m128i ek0 = aes128_encrypt(J0, rk);
    _mm_storeu_si128((__m128i*)tag, _mm_xor_si128(y, ek0));
}

int main() {
    uint8_t key[16], nonce[12], aad[32];
    FILE *f = fopen("/dev/urandom","rb");
    fread(key,1,16,f); fread(nonce,1,12,f); fread(aad,1,32,f);
    size_t N = 100000;
    uint8_t *pt = malloc(N), *ct = malloc(N), tag[16], ct2[/*heap*/1];
    uint8_t *ctref = malloc(N), tagref[16];
    fread(pt, 1, N, f); fclose(f);
    gcm_encrypt(key, nonce, 12, pt, N, aad, 32, ct, tag);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    int outlen = 0, total = 0;
    EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
    EVP_EncryptUpdate(ctx, ctref, &outlen, pt, (int)N); total = outlen;
    EVP_EncryptFinal_ex(ctx, ctref + total, &outlen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tagref);
    printf("ct match %d tag match %d\n", memcmp(ct, ctref, N)==0, memcmp(tag, tagref, 16)==0);

    /* empty aad */
    gcm_encrypt(key, nonce, 12, pt, N, NULL, 0, ct, tag);
    EVP_CIPHER_CTX_reset(ctx);
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, ctref, &outlen, pt, (int)N); total = outlen;
    EVP_EncryptFinal_ex(ctx, ctref + total, &outlen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tagref);
    printf("no-aad ct %d tag %d\n", memcmp(ct, ctref, N)==0, memcmp(tag, tagref, 16)==0);

    /* non-multiple length */
    size_t M = 1000;
    gcm_encrypt(key, nonce, 12, pt, M, aad, 32, ct, tag);
    EVP_CIPHER_CTX_reset(ctx);
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
    EVP_EncryptUpdate(ctx, ctref, &outlen, pt, (int)M); total = outlen;
    EVP_EncryptFinal_ex(ctx, ctref + total, &outlen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tagref);
    printf("partial ct %d tag %d\n", memcmp(ct, ctref, M)==0, memcmp(tag, tagref, 16)==0);

    /* bench */
    size_t BIG = 60ull*1024*1024;
    uint8_t *big = malloc(BIG), *bigct = malloc(BIG);
    memset(big, 0x5a, BIG);
    double t0 = now();
    gcm_encrypt(key, nonce, 12, big, BIG, aad, 32, bigct, tag);
    double t1 = now();
    printf("my gcm %.4f s  %.0f MB/s\n", t1-t0, (BIG/1e6)/(t1-t0));
    (void)ct2;
    return 0;
}
