        y = gmul_le(_mm_xor_si128(y, bitrev(o)), Hl);
    }
    if (ptlen % 16) {
        ctr = be32_inc(ctr);
        __m128i ks = aes_encrypt(ctr, rk, nrounds);
        uint8_t block[16] = {0};
        memcpy(block, pt + 16 * blocks, ptlen % 16);
        __m128i o = _mm_xor_si128(_mm_loadu_si128((__m128i *)block), ks);
        uint8_t ob[16];
        _mm_storeu_si128((__m128i *)ob, o);
        memcpy(ct + 16 * blocks, ob, ptlen % 16);
        memset(ob + (ptlen % 16), 0, 16 - (ptlen % 16));
        y = gmul_le(_mm_xor_si128(y, bitrev(_mm_loadu_si128((__m128i *)ob))), Hl);
    }

    uint8_t lenblock[16] = {0};
    uint64_t abits = (uint64_t)aadlen * 8, cbits = (uint64_t)ptlen * 8;
    for (int k = 0; k < 8; k++) lenblock[7 - k] = (uint8_t)(abits >> (8 * k));
    for (int k = 0; k < 8; k++) lenblock[15 - k] = (uint8_t)(cbits >> (8 * k));
    y = gmul_le(_mm_xor_si128(y, bitrev(_mm_loadu_si128((__m128i *)lenblock))), Hl);
    y = bitrev(y);
    __m128i ek0 = aes_encrypt(J0, rk, nrounds);
    _mm_storeu_si128((__m128i *)tag, _mm_xor_si128(y, ek0));
}

/* ---------- Python wrapper ---------- */

static PyObject *py_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    PyObject *aad_obj;
    memset(&aad, 0, sizeof(aad));
    if (!PyArg_ParseTuple(args, "y*y*y*O", &key, &nonce, &pt, &aad_obj)) return NULL;
    if (key.len != 16 && key.len != 24 && key.len != 32) {
        PyErr_SetString(PyExc_ValueError, "key must be 16, 24 or 32 bytes");
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
        return NULL;
    }
    int have_aad = 0;
    if (aad_obj != Py_None) {
        if (PyObject_GetBuffer(aad_obj, &aad, PyBUF_SIMPLE) != 0) {
            PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
            return NULL;
        }
        have_aad = 1;
    }
    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, pt.len > 0 ? pt.len : 1);
    if (!ct_obj) { if (have_aad) PyBuffer_Release(&aad); PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); return NULL; }
    uint8_t tag[16];
    Py_BEGIN_ALLOW_THREADS
    gcm_encrypt((const uint8_t *)key.buf, (int)key.len, (const uint8_t *)nonce.buf, (int)nonce.len,
                (const uint8_t *)pt.buf, (size_t)pt.len,
                have_aad ? (const uint8_t *)aad.buf : NULL, have_aad ? (size_t)aad.len : 0,
                (uint8_t *)PyBytes_AS_STRING(ct_obj), tag);
    Py_END_ALLOW_THREADS
    Py_ssize_t ptlen = pt.len;
    if (have_aad) PyBuffer_Release(&aad);
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if (ptlen == 0 && _PyBytes_Resize(&ct_obj, 0) != 0) return NULL;
    PyObject *tag_obj = PyBytes_FromStringAndSize((const char *)tag, 16);
    return Py_BuildValue("NN", ct_obj, tag_obj);
}

static PyMethodDef methods[] = {
    {"encrypt", py_encrypt, METH_VARARGS, "AES-GCM encrypt"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "aesgcm_fast", NULL, -1, methods};
PyMODINIT_FUNC PyInit_aesgcm_fast(void) { return PyModule_Create(&moduledef); }
EOF
